import apps.procurement.models


def backfill_legacy_order_versions(apps, schema_editor):
    del schema_editor
    PurchaseOrder = apps.get_model("procurement", "PurchaseOrder")
    PurchaseOrderItem = apps.get_model("procurement", "PurchaseOrderItem")
    PurchaseOrderVersion = apps.get_model("procurement", "PurchaseOrderVersion")
    PurchaseOrderVersionLine = apps.get_model("procurement", "PurchaseOrderVersionLine")
    GoodsReceipt = apps.get_model("procurement", "GoodsReceipt")
    for order in PurchaseOrder.objects.exclude(status="draft").iterator():
        items = list(
            PurchaseOrderItem.objects.filter(purchase_order=order).order_by(
                "sort_order", "created_at"
            )
        )
        if not items:
            continue
        payload = [
            {
                "source_item": str(item.pk),
                "award_allocation": str(item.source_award_allocation_id or ""),
                "material": str(item.material_id),
                "unit": str(item.unit_of_measure_id),
                "description": item.description,
                "quantity": str(item.quantity),
                "unit_price": str(item.unit_price),
                "sort_order": item.sort_order,
            }
            for item in items
        ]
        payload_hash = hashlib.sha256(
            json.dumps(payload, sort_keys=True, separators=(",", ":")).encode()
        ).hexdigest()
        version = PurchaseOrderVersion.objects.create(
            organization_id=order.organization_id,
            purchase_order=order,
            version_number=1,
            source_award_id=order.source_award_id,
            effective_at=order.issued_at or order.created_at,
            reason="Legacy issued-order snapshot",
            payload_hash=payload_hash,
            idempotency_key=f"legacy-backfill:{order.pk}",
            created_by_id=order.issued_by_id or order.created_by_id,
        )
        for item in items:
            PurchaseOrderVersionLine.objects.create(
                organization_id=order.organization_id,
                version=version,
                source_item=item,
                award_allocation_id=item.source_award_allocation_id,
                material_id=item.material_id,
                unit_of_measure_id=item.unit_of_measure_id,
                description=item.description,
                quantity=item.quantity,
                unit_price=item.unit_price,
                sort_order=item.sort_order,
            )
        order.current_version_id = version.pk
        order.save(update_fields=["current_version"])
        GoodsReceipt.objects.filter(purchase_order=order).update(
            purchase_order_version=version
        )


